name: Agentic Kanban Worker

on:
  schedule:
    - cron: '*/30 * * * *'  # run every 30 minutes
  workflow_dispatch:

env:
  GITHUB_PROJECTS_TOKEN: ${{ secrets.GITHUB_PROJECTS_TOKEN }}
  GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
  PROJECT_ID: ${{ secrets.PROJECT_ID }}
  AGENT_NAME: rust-agent
  SESSION_ID: ${{ github.run_id }}

jobs:
  agentic_worker:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Set up Rust
        uses: actions/setup-rust@v2
        with:
          rust-version: stable

      - name: Install dependencies
        run: cargo fetch

      - name: Query board for unblocked TODO tasks
        id: query
        uses: actions/github-script@v6
        env:
          PROJECT_ID: ${{ secrets.PROJECT_ID }}
          GITHUB_PROJECTS_TOKEN: ${{ secrets.GITHUB_PROJECTS_TOKEN }}
        with:
          script: |
            const projectId = process.env.PROJECT_ID;
            const query = `
              query($projectId: ID!) {
                node(id: $projectId) {
                  ... on ProjectV2 {
                    items(first: 100) {
                      nodes {
                        id
                        content {
                          ... on Issue {
                            id
                            title
                            state
                            labels(first: 10) {
                              nodes { name }
                            }
                            projectItems(first: 10) {
                              nodes {
                                fieldValueByName(name: "Status") {
                                  ... on ProjectV2ItemFieldSingleSelectValue {
                                    name
                                  }
                                }
                                fieldValueByName(name: "Blocked") {
                                  ... on ProjectV2ItemFieldBooleanValue {
                                    value
                                  }
                                }
                              }
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            `;
            const variables = { projectId };
            const result = await github.graphql(query, variables, {
              headers: { authorization: `Bearer ${process.env.GITHUB_PROJECTS_TOKEN}` }
            });
            const items = result.node.items.nodes;
            const unblocked = items.filter(item => {
              const content = item.content;
              if (!content) return false;
              const statusField = content.projectItems.nodes.find(f => f.fieldValueByName && f.fieldValueByName.name === "Status");
              const blockedField = content.projectItems.nodes.find(f => f.fieldValueByName && f.fieldValueByName.value === true);
              return statusField && statusField.fieldValueByName.name === "TODO" && !blockedField;
            });
            console.log(JSON.stringify(unblocked));
            return unblocked;

      - name: Claim a task
        id: claim
        if: steps.query.outputs.result != ''
        uses: actions/github-script@v6
        env:
          PROJECT_ID: ${{ secrets.PROJECT_ID }}
          GITHUB_PROJECTS_TOKEN: ${{ secrets.GITHUB_PROJECTS_TOKEN }}
          AGENT_NAME: ${{ env.AGENT_NAME }}
          TASKS: ${{ steps.query.outputs.result }}
        with:
          script: |
            const tasks = JSON.parse(process.env.TASKS);
            if (!tasks || tasks.length === 0) {
              console.log("No tasks to claim");
              return;
            }
            const task = tasks[0];
            const itemId = task.id;
            const projectId = process.env.PROJECT_ID;
            const fieldQuery = `
              query($projectId: ID!) {
                node(id: $projectId) {
                  ... on ProjectV2 {
                    fields(first: 10) {
                      nodes {
                        id
                        name
                        ... on ProjectV2ItemFieldSingleSelect {
                          options {
                            id
                            name
                          }
                        }
                      }
                    }
                  }
                }
              }
            `;
            const fieldResult = await github.graphql(fieldQuery, { projectId }, {
              headers: { authorization: `Bearer ${process.env.GITHUB_PROJECTS_TOKEN}` }
            });
            const claimedByField = fieldResult.node.fields.nodes.find(f => f.name === "Claimed By");
            if (!claimedByField) {
              console.log("Claimed By field not found");
              return;
            }
            const option = claimedByField.options.find(o => o.name === process.env.AGENT_NAME);
            if (!option) {
              console.log("Agent option not found in Claimed By field");
              return;
            }
            const mutation = `
              mutation($projectId: ID!, $itemId: ID!, $fieldId: ID!, $valueId: ID!) {
                updateProjectV2ItemFieldValue(input: {
                  projectId: $projectId,
                  itemId: $itemId,
                  fieldId: $fieldId,
                  valueId: $valueId
                }) {
                  projectV2Item {
                    id
                  }
                }
              }
            `;
            await github.graphql(mutation, {
              projectId,
              itemId,
              fieldId: claimedByField.id,
              valueId: option.id
            }, {
              headers: { authorization: `Bearer ${process.env.GITHUB_PROJECTS_TOKEN}` }
            });
            console.log("Claimed task", itemId);
            return { itemId, fieldId: claimedByField.id, valueId: option.id };

      - name: Run task
        if: steps.claim.outputs.result != ''
        run: |
          echo "Running task for item ${{ fromJSON(steps.claim.outputs.result).itemId }}"
          # Example task: run Rust tests
          cargo test -- --test-threads=1

      - name: Release task
        if: steps.claim.outputs.result != ''
        uses: actions/github-script@v6
        env:
          PROJECT_ID: ${{ secrets.PROJECT_ID }}
          GITHUB_PROJECTS_TOKEN: ${{ secrets.GITHUB_PROJECTS_TOKEN }}
          CLAIM: ${{ steps.claim.outputs.result }}
        with:
          script: |
            const claim = JSON.parse(process.env.CLAIM);
            const { itemId, fieldId } = claim;
            const mutation = `
              mutation($projectId: ID!, $itemId: ID!, $fieldId: ID!) {
                updateProjectV2ItemFieldValue(input: {
                  projectId: $projectId,
                  itemId: $itemId,
                  fieldId: $fieldId,
                  valueId: null
                }) {
                  projectV2Item {
                    id
                  }
                }
              }
            `;
            await github.graphql(mutation, {
              projectId: process.env.PROJECT_ID,
              itemId,
              fieldId
            }, {
              headers: { authorization: `Bearer ${process.env.GITHUB_PROJECTS_TOKEN}` }
            });
            console.log("Released task", itemId);
